// Mapa de Colombia continental: país y departamentos.
// Fuente: DANE, Marco Geoestadístico Nacional (límites municipales publicados en
// github.com/santiblanko/colombia.geojson). Se simplificó por arcos compartidos para que
// los bordes entre departamentos y municipios coincidan sin rendijas.
// Los municipios de cada departamento están en /public/mapa/departamentos/<código>.json
// y se cargan solo cuando alguien entra a ese departamento.
// Proyección Mercator preajustada al lienzo; usa proyectar() para ubicar cualquier lon/lat.

export const COL_WIDTH = 620
export const COL_HEIGHT = 830

const ESCALA = 2727.648207
const OFFSET_X = 3775.0171
const OFFSET_Y = 612.9378

export function proyectar(lon: number, lat: number): [number, number] {
  const x = (lon * Math.PI) / 180
  const y = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360))
  // Redondear las coordenadas evita que el servidor y el navegador serialicen
  // el mismo cálculo con los últimos bits de coma flotante de forma distinta.
  return [
    Number((x * ESCALA + OFFSET_X).toFixed(4)),
    Number((OFFSET_Y - y * ESCALA).toFixed(4)),
  ]
}

export type Departamento = {
  /** Código DANE de dos dígitos. */
  codigo: string
  nombre: string
  /** Contorno simplificado para la vista nacional. */
  d: string
  /** Caja [x, y, ancho, alto] en coordenadas del lienzo, para encuadrar el zoom. */
  caja: [number, number, number, number]
}

